/**
 * Asset module declarations for bundler-resolved media
 */

declare module '*.wav' {
  const content: number;
  export default content;
}

declare module '*.mp3' {
  const content: number;
  export default content;
}

declare module '*.png' {
  const content: number;
  export default content;
}

declare module '*.jpg' {
  const content: number;
  export default content;
}

declare module '*.jpeg' {
  const content: number;
  export default content;
}
